// Prüft die Signatur, damit nur Dokufy Termine anlegen kann.
const crypto = require('crypto');
const item = $input.first();
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const sig = item.json.headers['x-dokufy-signature'];
const expected = crypto.createHmac('sha256', $env.DOKUFY_WEBHOOK_SECRET).update(raw).digest('hex');
if (!sig || sig.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
  throw new Error('Ungültige Signatur – Ereignis verworfen.');
}
return [{ json: JSON.parse(raw) }];

// Ganztägiger Termin mit Erinnerungen 7, 3 und 1 Tag vorher.
const e = $input.first().json;
const d = e.deadline;
const day = d.date.replace(/-/g, '');
const next = new Date(d.date + 'T00:00:00Z'); next.setUTCDate(next.getUTCDate() + 1);
const end = next.toISOString().slice(0, 10).replace(/-/g, '');
const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
const label = { zahlung: 'Zahlung', einspruch: 'Einspruchsfrist', antwort: 'Antwort fällig', kuendigung: 'Kündigungsfrist', allgemein: 'Frist' }[d.kind];
const alarms = [7, 3, 1].map((n) => `BEGIN:VALARM\r\nACTION:DISPLAY\r\nDESCRIPTION:${esc(e.caseTitle)}\r\nTRIGGER:-P${n}D\r\nEND:VALARM`).join('\r\n');
const uid = `dokufy-${e.caseId}-${d.kind}`;
const ics = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dokufy//n8n//DE','BEGIN:VEVENT',`UID:${uid}`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${day}`,`DTEND;VALUE=DATE:${end}`,`SUMMARY:${esc(label + ': ' + e.caseTitle)}`,`DESCRIPTION:${esc(d.explanation)}`,alarms,'END:VEVENT','END:VCALENDAR'].join('\r\n');
return [{ json: { uid, ics } }];
